package io.github.jackotom.hongguo.android;

import java.io.*;
import java.lang.reflect.*;
import java.net.UnknownHostException;
import java.util.*;
import javax.net.ssl.SSLHandshakeException;
import org.json.*;

/** Production first-play registration and bounded callback ownership; transports are offline doubles. */
public final class InitialPlaybackFallbackTest {
    static final String SID="970001",VID="970006",KEY="00112233445566778899aabbccddeeff";
    static int passed,failed,checks;static MainActivity host;static final List<JSONArray> calls=new ArrayList<>();
    interface Checked{void run()throws Exception;}
    static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    static Exception rejects(Checked task,String message)throws Exception{try{task.run();}catch(Exception expected){checks++;return expected;}throw new AssertionError(message);}
    static void group(String name,Checked task){try{reset();requireEntry();task.run();passed++;System.out.println("PASS "+name);}catch(Throwable error){failed++;System.out.println("FAIL "+name+": "+error.getClass().getSimpleName()+" "+error.getMessage());}finally{Thread.interrupted();}}
    static Method requireEntry(){try{return PlaybackSources.class.getDeclaredMethod("registerInitial",JSONObject.class,String.class,String.class,String.class);}catch(NoSuchMethodException missing){throw new AssertionError("missing initial registration fallback entrypoint");}}
    static PlaybackSources.Plan initial(JSONObject input,String sid,String vid,String quality)throws Exception{try{return(PlaybackSources.Plan)requireEntry().invoke(null,input,sid,vid,quality);}catch(InvocationTargetException wrapped){Throwable cause=wrapped.getCause();if(cause instanceof Exception)throw(Exception)cause;throw(Error)cause;}}
    @SuppressWarnings("unchecked") static Map<String,Long> penalties()throws Exception{Field field=PlaybackSources.class.getDeclaredField("failedWebUntil");field.setAccessible(true);return(Map<String,Long>)field.get(null);}
    @SuppressWarnings("unchecked") static void reset()throws Exception{NetworkGuard.reset();calls.clear();Map<String,Long> penalties=penalties();synchronized(penalties){penalties.clear();}Field field=PlaybackSources.class.getDeclaredField("plans");field.setAccessible(true);Map<String,PlaybackSources.Plan> registry=(Map<String,PlaybackSources.Plan>)field.get(null);synchronized(registry){registry.clear();}replySuccess(model("unused","auto"));}
    static JSONObject web(String name)throws Exception{return new JSONObject().put("url","https://cdn.example.net/fixture-initial-"+name+".mp4").put("source","web").put("seriesId",SID).put("vid",VID).put("requestedQuality","auto");}
    static JSONObject model(String name,String quality)throws Exception{JSONObject info=new JSONObject().put("url","https://cdn.qznovelvod.com/fixture-initial-"+name+".mp4").put("source","app").put("seriesId",SID).put("vid",VID).put("contentKey",KEY).put("requestedQuality",quality);if(!quality.equals("auto"))info.put("width",1920).put("height",1080);return info;}
    static JSONArray arguments(String script)throws Exception{return new JSONArray("["+script.substring(script.lastIndexOf('(')+1,script.length()-1)+"]");}
    static JSONObject envelope(JSONArray a)throws Exception{return new JSONObject().put("requestId",a.getString(0)).put("seriesId",a.getString(1)).put("vid",a.getString(2)).put("requestedQuality",a.getString(3));}
    static void replySuccess(JSONObject info){host.callback=script->{try{JSONArray a=arguments(script);calls.add(a);PlaybackSources.result(envelope(a).put("playInfo",info));}catch(Exception error){throw new RuntimeException(error);}};}
    static void exactRequest(String quality)throws Exception{for(JSONArray request:calls)check(request.getString(1).equals(SID)&&request.getString(2).equals(VID)&&request.getString(3).equals(quality),"fallback keeps exact series, episode and requested quality");}
    static void untouched(){check(NetworkGuard.heads==0&&AppTransport.heads==0&&calls.isEmpty()&&NetworkGuard.downloads==0&&EpisodeResolver.calls==0,"invalid plan rejected before all provider/probe/transfer work");}
    public static void main(String[]unused)throws Exception{
        host=new MainActivity();PlaybackSources.attach(host);
        try{
            group("valid web registration probes once and does not resolve App",()->{JSONObject info=web("success");PlaybackSources.Plan p=initial(info,SID,VID,"auto");check(p.url.equals(info.getString("url"))&&p.source.equals("web")&&p.seriesId.equals(SID),"web result retains binding");check(NetworkGuard.heads==1&&calls.isEmpty()&&NetworkGuard.downloads==0&&EpisodeResolver.calls==0,"web preflight is single owned probe without lookup");check(PlaybackSources.find(p.url,"auto")==p,"successful first plan registered");});
            group("already resolved App plans skip all HEAD probes at exact quality",()->{for(String quality:new String[]{"auto","720p","1080p"}){reset();JSONObject info=model("resolved-"+quality,quality);PlaybackSources.Plan p=initial(info,SID,VID,quality);check(p.requestedQuality.equals(quality)&&p.source.equals("app")&&p.seriesId.equals(SID),"App plan identity and requested quality survive");untouched();check(PlaybackSources.find(p.url,quality)==p,"App registry keyed by exact quality");}});
            group("valid web redirect TLS HTTP405 and typed DNS probe failures use one App lookup",()->{Exception[] failures={new IOException("仅允许HTTPS服务地址"),new SSLHandshakeException("fixture TLS preflight failure"),new IOException("片源响应 HTTP 405"),new UnknownHostException("fixture preflight DNS")};for(int i=0;i<failures.length;i++){reset();JSONObject broken=web("broken-"+i),fresh=model("fallback-"+i,"auto");NetworkGuard.probeError=failures[i];replySuccess(fresh);PlaybackSources.Plan p=initial(broken,SID,VID,"auto");check(p.url.equals(fresh.getString("url"))&&p.source.equals("app")&&p.requestedQuality.equals("auto"),"preflight failure produces matching App plan");check(NetworkGuard.heads==1&&AppTransport.heads==0&&calls.size()==1&&EpisodeResolver.calls==0&&NetworkGuard.downloads==0,"failure gets exactly one App lookup and no nested probe/transfer");exactRequest("auto");check(PlaybackSources.find(broken.getString("url"))==null&&PlaybackSources.find(p.url)==p,"broken web never enters registry; valid App does");long left=penalties().get(SID+"\n"+VID)-System.nanoTime();check(left>295_000_000_000L&&left<=300_000_000_000L&&penalties().size()==1,"web penalty scoped to this series and episode for five minutes");}});
            group("invalid identity URL key headers quality and variants never trigger fallback",()->{
                for(JSONObject invalid:Arrays.asList(web("http").put("url","http://cdn.example.net/not-https.mp4"),web("wrong-vid").put("vid","970007"),web("wrong-series").put("seriesId","970002"),web("bad-key").put("contentKey",KEY),web("bad-agent").put("userAgent","a\r\nb"),web("bad-ref").put("referer","https://unrelated.example/"),web("bad-quality").put("requestedQuality","4k"),web("variant-http").put("variants",new JSONArray().put(web("invalid-child").put("url","http://cdn.example.net/child.mp4"))),web("variant-key").put("variants",new JSONArray().put(web("invalid-key-child").put("contentKey","wrong"))),web("variant-vid").put("variants",new JSONArray().put(web("invalid-vid-child").put("vid","970007"))))){reset();NetworkGuard.probeError=new IOException("fixture must not reach probe");rejects(()->initial(invalid,SID,VID,"auto"),"invalid input accepted");untouched();check(penalties().isEmpty(),"invalid input never penalizes valid web sources");}
                for(String[] ids:new String[][]{{"../",VID},{SID,"bad"},{null,VID},{SID,null}}){reset();rejects(()->initial(web("invalid-id"),ids[0],ids[1],"auto"),"invalid id accepted");untouched();}
                reset();rejects(()->initial(web("invalid-quality"),SID,VID,"4k"),"invalid quality accepted");untouched();
            });
            group("explicit quality never falls back from unmeasured web or mismatched metadata",()->{for(JSONObject info:Arrays.asList(web("explicit-web").put("requestedQuality","1080p"),model("request-mismatch","auto"),model("undersized","1080p").put("height",720),model("variant-small","1080p").put("variants",new JSONArray().put(model("small-child","1080p").put("height",720))))){reset();rejects(()->initial(info,SID,VID,"1080p"),"unverified or mismatched explicit plan accepted");untouched();}});
            group("cancellation and wrapped interrupt take precedence over fallback",()->{for(Exception error:new Exception[]{new InterruptedIOException("fixture direct cancellation"),new IOException("fixture wrapper",new InterruptedIOException("fixture wrapped cancellation")),new IOException("fixture nested wrapper",new IOException("fixture inner",new InterruptedException("fixture interrupted child")))}){reset();NetworkGuard.probeError=error;rejects(()->initial(web("cancelled"),SID,VID,"auto"),"cancelled preflight resolved App");check(NetworkGuard.heads==1&&calls.isEmpty()&&penalties().isEmpty(),"cancellation makes no fallback and does not penalize web");}reset();Thread.currentThread().interrupt();rejects(()->initial(web("thread-cancelled"),SID,VID,"auto"),"interrupted thread registered initial plan");check(calls.isEmpty()&&NetworkGuard.heads==0,"already interrupted work does not probe or resolve");Thread.interrupted();});
            group("App failure terminates with original web error suppressed and no loop",()->{JSONObject input=web("app-unavailable");IOException webError=new IOException("fixture original web probe error");NetworkGuard.probeError=webError;host.callback=script->{try{JSONArray a=arguments(script);calls.add(a);PlaybackSources.result(envelope(a).put("error","fixture App unavailable").put("errorCode","BUSINESS_REJECTED"));}catch(Exception error){throw new RuntimeException(error);}};Exception failure=rejects(()->initial(input,SID,VID,"auto"),"unavailable App returned success");check(calls.size()==1&&NetworkGuard.heads==1&&EpisodeResolver.calls==0&&NetworkGuard.downloads==0,"App failure terminates without web loop");check(Arrays.asList(failure.getSuppressed()).contains(webError),"failure retains original web probe as suppressed cause");check(PlaybackSources.find(input.getString("url"))==null,"failure does not cache broken web plan");exactRequest("auto");});
            group("typed transient initial lookup retries once with fresh request ownership",()->{JSONObject info=web("bounded-lookup"),fresh=model("bounded-fresh","auto");NetworkGuard.probeError=new IOException("fixture web preflight failed");host.callback=script->{try{JSONArray a=arguments(script);calls.add(a);if(calls.size()==1)PlaybackSources.result(envelope(a).put("error","fixture typed lookup timeout").put("errorCode","ETIMEDOUT"));else PlaybackSources.result(envelope(a).put("playInfo",fresh));}catch(Exception error){throw new RuntimeException(error);}};PlaybackSources.Plan p=initial(info,SID,VID,"auto");check(calls.size()==2&&!calls.get(0).getString(0).equals(calls.get(1).getString(0))&&p.url.equals(fresh.getString("url")),"single fresh retry uses new opaque request id");exactRequest("auto");reset();NetworkGuard.probeError=new IOException("fixture web failed again");host.callback=script->{try{JSONArray a=arguments(script);calls.add(a);PlaybackSources.result(envelope(a).put("error","fixture repeated timeout").put("errorCode","ETIMEDOUT"));}catch(Exception error){throw new RuntimeException(error);}};rejects(()->initial(web("two-failed"),SID,VID,"auto"),"two failed lookups returned media");check(calls.size()==2&&NetworkGuard.heads==1&&NetworkGuard.downloads==0,"two failed lookup attempts terminate without multiplying probes");});
            System.out.println("INITIAL_PLAYBACK_"+(failed==0?"OK":"FAILED")+" groupsPassed="+passed+" groupsFailed="+failed+" checks="+checks+" networkRequests=0 deviceTests=not_run");
            if(failed!=0)throw new AssertionError("initial playback fallback tests failed");
        }finally{PlaybackSources.detach(host);Thread.interrupted();}
    }
}
